import numpy as np

def branches(sh,t,L1,L2):
 sh=np.array(sh,float); t=np.array(t,float); d=t-sh; dist=np.linalg.norm(d); u=d/dist; a=(L1*L1-L2*L2+dist*dist)/(2*dist); h=np.sqrt(max(0,L1*L1-a*a)); b=sh+u*a; p=np.array([-u[1],u[0]]); return b+p*h,b-p*h
for L in [(120,120),(110,120),(100,120),(90,110)]:
 print('L',L)
 for t in [(120,120),(50,110),(75,51),(126,38),(174,41),(190,41),(132,121)]: print(t,[x.round(1).tolist() for x in branches((0,180),t,*L)])
